import { Hono } from 'hono'
import {
  createDirectSale,
  voidSale,
  type SaleResult,
  InsufficientStockError,
  SaleNotFoundError,
  listSales,
  findSaleById,
  findLineItemsBySaleId,
  findPaymentsBySaleId,
  findMovementsBySaleId
} from '../services/sale.service.js'

const salesRoutes = new Hono()

// ============================================================================
// POST /sales — Create a direct sale
// ============================================================================

/**
 * Error response shape.
 */
interface ErrorResponse {
  error: string
  code?: string
  shortfalls?: Array<{ partId: string; requested: number; available: number }>
}

salesRoutes.post('/', async (c) => {
  try {
    const rawInput = await c.req.json()

    const result: SaleResult = await createDirectSale(rawInput)

    return c.json(
      {
        sale: Object.fromEntries(Object.entries(result.sale)),
        payment: Object.fromEntries(Object.entries(result.payment)),
        lineItems: result.lineItems.map(item => Object.fromEntries(Object.entries(item)))
      },
      201
    )
  } catch (err) {
    if (err instanceof InsufficientStockError) {
      return c.json(
        {
          error: 'Insufficient stock',
          code: 'INSUFFICIENT_STOCK',
          shortfalls: err.shortfalls
        } as ErrorResponse,
        409
      )
    }

    if (err instanceof Error && err.message.startsWith('Invalid sale input')) {
      return c.json(
        { error: err.message, code: 'VALIDATION_ERROR' } as ErrorResponse,
        400
      )
    }

    console.error('[POST /sales] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// GET /sales — List recent sales history
// ============================================================================

interface SalesListResponse {
  /** Array of sale records (newest first) */
  sales: Record<string, unknown>[]
  /** Total count of all sales */
  total: number
}

salesRoutes.get('/', async (c) => {
  const limit = Math.min(parseInt(c.req.query('limit') ?? '50', 10) || 50, 200)

  const saleRows = await listSales(limit)
  const total = await listSales(999999).then(rows => rows.length)

  return c.json({
    sales: saleRows.map(row => Object.fromEntries(Object.entries(row))),
    total
  } as SalesListResponse)
})

// ============================================================================
// GET /sales/:id — Get a single sale with full details
// ============================================================================

interface SaleDetailResponse {
  /** The sale header */
  sale: Record<string, unknown>
  /** Line items for this sale */
  lineItems: Record<string, unknown>[]
  /** Payments allocated to this sale */
  payments: Record<string, unknown>[]
  /** Stock movements referencing this sale */
  stockMovements: Record<string, unknown>[]
}

salesRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')

  const sale = await findSaleById(id)
  if (!sale) {
    return c.json({ error: 'Sale not found', code: 'NOT_FOUND' }, 404)
  }

  const [lineItems, payments, stockMovements] = await Promise.all([
    findLineItemsBySaleId(id),
    findPaymentsBySaleId(id),
    findMovementsBySaleId(id)
  ])

  return c.json({
    sale: Object.fromEntries(Object.entries(sale)),
    lineItems: lineItems.map(item => Object.fromEntries(Object.entries(item))),
    payments: payments.map(payment => Object.fromEntries(Object.entries(payment))),
    stockMovements: stockMovements.map(mvmt => Object.fromEntries(Object.entries(mvmt)))
  } as SaleDetailResponse)
})

// ============================================================================
// PATCH /sales/:id/void — Void a completed sale
// ============================================================================

salesRoutes.patch('/:id/void', async (c) => {
  const id = c.req.param('id')

  try {
    const updatedSale = await voidSale(id)

    return c.json({
      sale: Object.fromEntries(Object.entries(updatedSale))
    })
  } catch (err) {
    if (err instanceof SaleNotFoundError) {
      return c.json(
        { error: 'Sale not found', code: 'NOT_FOUND' },
        404
      )
    }

    if (err instanceof Error && err.message.includes('already voided')) {
      return c.json(
        { error: err.message, code: 'ALREADY_VOIDED' },
        409
      )
    }

    console.error('[PATCH /sales/:id/void] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

export default salesRoutes

import { Hono } from 'hono'
import { db } from '@/db/index.js'
import { bicycles } from '@/db/schema.js'
import { eq } from 'drizzle-orm'

const bicyclesRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /api/bicycles/:id — Get a single bicycle by ID (includes isLease flag)
// ===========================================================================

bicyclesRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')

  const [bicycle] = await db.select().from(bicycles).where(eq(bicycles.id, id))
  if (!bicycle) {
    return c.json({ error: 'Bicycle not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json({ bicycle })
})

export default bicyclesRoutes

import { Hono } from 'hono'
import {
  createCustomerOrder,
  listCustomerOrders,
  findCustomerOrderById,
  transitionCustomerOrder,
  updateCustomerOrderFields,
  completeCustomerOrder,
  cancelCustomerOrder,
  getCustomerOrderHistory,
  LeasedBicycleDepositError,
  InvalidTransitionError,
  EditabilityError,
  InsufficientPaymentError,
} from '../services/customer-order.service.js'

const ordersRoutes = new Hono()

// ============================================================================
// POST /api/orders — Create a customer order with optional deposit
// ============================================================================

interface ErrorResponse {
  error: string
  code?: string
}

ordersRoutes.post('/', async (c) => {
  try {
    const rawInput = await c.req.json()

    const result = await createCustomerOrder(rawInput)

    return c.json(
      {
        order: Object.fromEntries(Object.entries(result.order)),
        lineItems: result.lineItems.map(item => Object.fromEntries(Object.entries(item))),
        payment: result.payment ? Object.fromEntries(Object.entries(result.payment)) : undefined,
        allocation: result.allocation ? Object.fromEntries(Object.entries(result.allocation)) : undefined,
      },
      201
    )
  } catch (err) {
    if (err instanceof LeasedBicycleDepositError) {
      return c.json(
        { error: err.message, code: 'LEASED_BICYCLE_DEPOSIT' } as ErrorResponse,
        409
      )
    }

    if (err instanceof Error && err.message.startsWith('Invalid order input')) {
      return c.json(
        { error: err.message, code: 'VALIDATION_ERROR' } as ErrorResponse,
        400
      )
    }

    console.error('[POST /api/orders] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// GET /api/orders — List customer orders with optional status filter
// ============================================================================

interface OrdersListResponse {
  orders: Record<string, unknown>[]
  total: number
}

ordersRoutes.get('/', async (c) => {
  const status = c.req.query('status') as 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled' | undefined

  const result = await listCustomerOrders(status ? { status } : undefined)

  return c.json({
    orders: result.orders.map(order => Object.fromEntries(Object.entries(order))),
    total: result.total,
  } as OrdersListResponse)
})

// ============================================================================
// GET /api/orders/:id — Get a single order with full details
// ============================================================================

interface OrderDetailResponse {
  order: Record<string, unknown>
  lineItems: Record<string, unknown>[]
  depositPaid: number
}

ordersRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')

  const detail = await findCustomerOrderById(id)
  if (!detail) {
    return c.json({ error: 'Order not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json({
    order: Object.fromEntries(Object.entries(detail.order)),
    lineItems: detail.lineItems.map(item => Object.fromEntries(Object.entries(item))),
    depositPaid: detail.depositPaid,
  } as OrderDetailResponse)
})

// ============================================================================
// PATCH /api/orders/:id/transition — Status transition with validation
// ============================================================================

ordersRoutes.patch('/:id/transition', async (c) => {
  const id = c.req.param('id')
  const body = await c.req.json()
  const newStatus = body.status as 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled'

  if (!newStatus || !['pending', 'ordered', 'ready', 'fulfilled', 'cancelled'].includes(newStatus)) {
    return c.json(
      { error: 'Invalid status', code: 'VALIDATION_ERROR' } as ErrorResponse,
      400
    )
  }

  try {
    const updated = await transitionCustomerOrder(id, newStatus, {
      expectedDeliveryDate: body.expectedDeliveryDate ?? undefined,
      internalNotes: body.internalNotes !== undefined ? body.internalNotes : undefined,
    })

    return c.json({
      order: Object.fromEntries(Object.entries(updated)),
    })
  } catch (err) {
    if (err instanceof InvalidTransitionError) {
      return c.json(
        { error: err.message, code: 'INVALID_TRANSITION' },
        409
      )
    }

    if (err instanceof Error && err.message.includes('not found')) {
      return c.json(
        { error: 'Order not found', code: 'NOT_FOUND' },
        404
      )
    }

    console.error('[PATCH /api/orders/:id/transition] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// PATCH /api/orders/:id — Update editable fields (notes/delivery date)
// ============================================================================

ordersRoutes.patch('/:id', async (c) => {
  const id = c.req.param('id')
  const body = await c.req.json()

  try {
    const updated = await updateCustomerOrderFields(id, {
      internalNotes: body.internalNotes !== undefined ? body.internalNotes : undefined,
      expectedDeliveryDate: body.expectedDeliveryDate !== undefined ? body.expectedDeliveryDate : undefined,
    })

    return c.json({
      order: Object.fromEntries(Object.entries(updated)),
    })
  } catch (err) {
    if (err instanceof EditabilityError) {
      return c.json(
        { error: err.message, code: 'FIELDS_LOCKED' },
        403
      )
    }

    if (err instanceof Error && err.message.includes('not found')) {
      return c.json(
        { error: 'Order not found', code: 'NOT_FOUND' },
        404
      )
    }

    if (err instanceof Error && err.message.toLowerCase().includes('nothing to update')) {
      return c.json(
        { error: err.message, code: 'VALIDATION_ERROR' },
        400
      )
    }

    console.error('[PATCH /api/orders/:id] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// POST /api/orders/:id/complete — Collect balance payment → create sale → fulfilled
// ============================================================================

ordersRoutes.post('/:id/complete', async (c) => {
  const id = c.req.param('id')
  const body = await c.req.json()
  const paymentLines = body.paymentLines as Array<{ method: 'cash' | 'card' | 'bank_transfer'; amount: number }>

  if (!Array.isArray(paymentLines) || paymentLines.length === 0) {
    return c.json(
      { error: 'paymentLines is required and must be a non-empty array', code: 'VALIDATION_ERROR' },
      400
    )
  }

  try {
    const result = await completeCustomerOrder(id, paymentLines)

    return c.json({
      order: Object.fromEntries(Object.entries(result.order)),
      sale: Object.fromEntries(Object.entries(result.sale)),
      payments: result.payments.map(p => Object.fromEntries(Object.entries(p))),
      saleLineItems: result.saleLineItems.map(item => Object.fromEntries(Object.entries(item))),
    })
  } catch (err) {
    if (err instanceof InsufficientPaymentError) {
      return c.json(
        { error: err.message, code: 'INSUFFICIENT_PAYMENT', expected: err.expected, provided: err.provided },
        400
      )
    }

    if (err instanceof Error && err.message.includes('not found')) {
      return c.json(
        { error: 'Order not found', code: 'NOT_FOUND' },
        404
      )
    }

    if (err instanceof Error && (err.message.includes('already fulfilled') || err.message.includes('cancelled'))) {
      return c.json(
        { error: err.message, code: 'INVALID_STATE' },
        409
      )
    }

    console.error('[POST /api/orders/:id/complete] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// PATCH /api/orders/:id/cancel — Cancel with refund rules applied
// ============================================================================

ordersRoutes.patch('/:id/cancel', async (c) => {
  const id = c.req.param('id')

  try {
    const result = await cancelCustomerOrder(id)

    return c.json({
      status: result.status,
      refundPayment: result.refundPayment ? Object.fromEntries(Object.entries(result.refundPayment)) : undefined,
    })
  } catch (err) {
    if (err instanceof Error && err.message.includes('not found')) {
      return c.json(
        { error: 'Order not found', code: 'NOT_FOUND' },
        404
      )
    }

    if (err instanceof Error && (err.message.includes('fulfilled') || err.message.includes('already cancelled'))) {
      return c.json(
        { error: err.message, code: 'INVALID_STATE' },
        409
      )
    }

    console.error('[PATCH /api/orders/:id/cancel] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// GET /api/orders/:id/history — Status transition history (oldest first)
// ============================================================================

ordersRoutes.get('/:id/history', async (c) => {
  const id = c.req.param('id')

  try {
    const history = await getCustomerOrderHistory(id)

    return c.json({
      history: history.map(entry => Object.fromEntries(Object.entries(entry))),
    })
  } catch (err) {
    if (err instanceof Error && err.message.includes('not found')) {
      return c.json(
        { error: 'Order not found', code: 'NOT_FOUND' },
        404
      )
    }

    console.error('[GET /api/orders/:id/history] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// PATCH /api/orders/:id/status — Legacy endpoint (backward compatibility)
// ============================================================================

ordersRoutes.patch('/:id/status', async (c) => {
  const id = c.req.param('id')
  const body = await c.req.json()
  const newStatus = body.status as 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled'

  if (!newStatus || !['pending', 'ordered', 'ready', 'fulfilled', 'cancelled'].includes(newStatus)) {
    return c.json(
      { error: 'Invalid status', code: 'VALIDATION_ERROR' } as ErrorResponse,
      400
    )
  }

  try {
    const updated = await transitionCustomerOrder(id, newStatus)

    return c.json({
      order: Object.fromEntries(Object.entries(updated)),
    })
  } catch (err) {
    if (err instanceof InvalidTransitionError) {
      return c.json(
        { error: err.message, code: 'INVALID_TRANSITION' },
        409
      )
    }

    if (err instanceof Error && err.message.includes('not found')) {
      return c.json(
        { error: 'Order not found', code: 'NOT_FOUND' },
        404
      )
    }

    console.error('[PATCH /api/orders/:id/status] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

export default ordersRoutes

import { Hono } from 'hono'
import {
  createRepairIntake,
  getRepairsList,
  getRepairById,
  transitionRepairStatus,
  updateRepairNotes,
  getCustomerWithBicycles,
  createRepairLineItem,
  updateRepairLineItem,
  deleteRepairLineItem,
  listLaborServices,
  getLaborServiceById,
  createLaborService,
  updateLaborService,
  deactivateLaborService,
  assignWorkerToRepair,
  startWorkTimer,
  stopWorkTimer,
  completeRepairPayment,
  type RepairDetail,
  type RepairStatus,
} from '../services/repair.service.js'

const repairsRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /repairs — Paginated list of repairs with filtering and sorting
//
// Query params:
//   status       - Filter by status (intake, in_progress, on_hold, verified, ready, completed, cancelled)
//   assignedTo   - Filter by worker ID or 'unassigned' for NULL assignments
//  pickupDate    - Filter by pickup date: 'today' or 'this_week'
//   page         - Page number (1-indexed, default 1)
//   pageSize     - Items per page (default 20)
//
// Default sort: planned_date DESC (most urgent first), then created_at DESC
// ---------------------------------------------------------------------------

repairsRoutes.get('/', async (c) => {
  const status = c.req.query('status') as string | undefined
  const assignedToRaw = c.req.query('assignedTo') as string | undefined
  const pickupDateFilter = c.req.query('pickupDate') as 'today' | 'this_week' | undefined
  const fromRaw = c.req.query('from') as string | undefined
  const toRaw = c.req.query('to') as string | undefined
  const statusInRaw = c.req.query('statusIn') as string | undefined
  const page = parseInt(c.req.query('page') || '1', 10)
  const pageSize = Math.min(parseInt(c.req.query('pageSize') || '20', 10), 100) // cap at 100

  // Build filters
  const filters: Parameters<typeof getRepairsList>[0] = {}

  if (status && ['intake', 'in_progress', 'on_hold', 'verified', 'ready', 'completed', 'cancelled'].includes(status)) {
    filters.status = status as RepairStatus
  }

  if (assignedToRaw === 'unassigned') {
    filters.assignedTo = null
  } else if (assignedToRaw) {
    filters.assignedTo = assignedToRaw
  }

  if (pickupDateFilter && ['today', 'this_week'].includes(pickupDateFilter)) {
    filters.pickupDateFilter = pickupDateFilter
  }

  // Date-range filtering (epoch ms)
  if (fromRaw) {
    const from = Number(fromRaw)
    if (!isNaN(from)) filters.from = from
  }
  if (toRaw) {
    const to = Number(toRaw)
    if (!isNaN(to)) filters.to = to
  }

  // Status-in filtering (comma-separated)
  if (statusInRaw) {
    filters.statusIn = statusInRaw.split(',').map(s => s.trim()).filter(Boolean)
  }

  const result = await getRepairsList(filters, page, pageSize)
  return c.json(result)
})

// ---------------------------------------------------------------------------
// POST /repairs — Create a new repair via intake flow
//
// Accepts customer (search existing or create inline), bicycle (select from
// customer's bikes or create inline with brand/model/color), and notes.
// Repairs are created with status='intake' and assignedTo=NULL.
// ---------------------------------------------------------------------------

repairsRoutes.post('/', async (c) => {
  const input = await c.req.json()

  try {
    const repair = await createRepairIntake(input)
    return c.json(repair, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      // Invalid JSON body
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    // Zod validation error or business logic error
    const message = err instanceof Error ? err.message : 'Validation failed'
    const status = (err as { code?: string; name?: string }).code === 'NOT_FOUND' || (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// GET /repairs/customers/:customerId — Get customer with bicycles for intake
// ---------------------------------------------------------------------------

repairsRoutes.get('/customers/:customerId', async (c) => {
  const customerId = c.req.param('customerId')
  const customerWithBicycles = await getCustomerWithBicycles(customerId)

  if (!customerWithBicycles) {
    return c.json({ error: 'Customer not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json(customerWithBicycles)
})

// ---------------------------------------------------------------------------
// GET /repairs/labor-services — List available labor services catalog
// ---------------------------------------------------------------------------

repairsRoutes.get('/labor-services', async (c) => {
  const billingType = c.req.query('billingType') as 'hourly' | 'fixed' | undefined

  try {
    const services = await listLaborServices(billingType ? { billingType } : {})
    return c.json({ laborServices: services, total: services.length })
  } catch (err) {
    console.error('[GET /labor-services] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Failed to fetch labor services', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// GET /repairs/labor-services/:id — Get single labor service detail
// ---------------------------------------------------------------------------

repairsRoutes.get('/labor-services/:id', async (c) => {
  const id = c.req.param('id')
  try {
    const service = await getLaborServiceById(id)
    if (!service) {
      return c.json({ error: 'Labor service not found', code: 'NOT_FOUND' }, 404)
    }
    return c.json(service)
  } catch (err) {
    console.error('[GET /labor-services/:id] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Failed to fetch labor service', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// POST /repairs/labor-services — Create a new labor service
// ---------------------------------------------------------------------------

repairsRoutes.post('/labor-services', async (c) => {
  const input = await c.req.json()

  try {
    if (!input?.name || !input.name.trim()) {
      return c.json({ error: 'Name is required', code: 'VALIDATION_ERROR' }, 400)
    }
    if (typeof input.defaultRate !== 'number' || input.defaultRate <= 0) {
      return c.json({ error: 'defaultRate must be a positive number', code: 'VALIDATION_ERROR' }, 400)
    }

    const service = await createLaborService(input)
    return c.json(service, 201)
  } catch (err) {
    console.error('[POST /labor-services] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Failed to create labor service', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// PATCH /repairs/labor-services/:id — Update a labor service
// ---------------------------------------------------------------------------

repairsRoutes.patch('/labor-services/:id', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    const service = await updateLaborService(id, input)
    return c.json(service)
  } catch (err) {
    if ((err as { name?: string }).name === 'LaborServiceNotFoundError') {
      return c.json({ error: 'Labor service not found', code: 'NOT_FOUND' }, 404)
    }
    console.error('[PATCH /labor-services/:id] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Failed to update labor service', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// PATCH /repairs/labor-services/:id/deactivate — Deactivate a labor service
// ---------------------------------------------------------------------------

repairsRoutes.patch('/labor-services/:id/deactivate', async (c) => {
  const id = c.req.param('id')

  try {
    await deactivateLaborService(id)
    return c.json({ success: true })
  } catch (err) {
    if ((err as { name?: string }).name === 'LaborServiceNotFoundError') {
      return c.json({ error: 'Labor service not found', code: 'NOT_FOUND' }, 404)
    }
    console.error('[PATCH /labor-services/:id/deactivate] Error:', err instanceof Error ? err.message : String(err))
    return c.json({ error: 'Failed to deactivate labor service', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// GET /repairs/:id — Get single repair detail
// ---------------------------------------------------------------------------

repairsRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')
  const repair = await getRepairById(id)

  if (!repair) {
    return c.json({ error: 'Repair not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json(repair)
})

// ---------------------------------------------------------------------------
// PATCH /repairs/:id/status — Transition repair status (canonical endpoint)
// ---------------------------------------------------------------------------

repairsRoutes.patch('/:id/status', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    const repair = await transitionRepairStatus(id, input)
    return c.json(repair as RepairDetail)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Transition failed'
    const status = (err as { name?: string }).name === 'RepairNotFoundError' ? 404 : 400

    return c.json({ error: message, code: (err as { name?: string }).name || 'VALIDATION_ERROR' }, status)
  }
})

// ---------------------------------------------------------------------------
// PATCH /repairs/:id/transition — Legacy alias for backward compatibility
// ---------------------------------------------------------------------------

repairsRoutes.patch('/:id/transition', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

