const customersRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /customers — List all customers for the POS customer selector dropdown.
//
// When called without query parameters, returns a compact shape:
// id, displayName (firstName+lastName or companyName), type.
// Suitable for populating a search/select dropdown component.
//
// When called with ?search= and/or ?page= parameters, returns full customer
// details with pagination — suitable for the management list view.
// ---------------------------------------------------------------------------

customersRoutes.get('/', async (c) => {
  const search = c.req.query('search')
  const page = c.req.query('page')
  const pageSize = c.req.query('pageSize')

  // If pagination or search params are present, return paginated full details
  if (search !== undefined || page !== undefined || pageSize !== undefined) {
    const query: CustomerListQuery = {}
    if (search !== undefined && search !== '') query.search = search
    if (page !== undefined) query.page = parseInt(page, 10)
    if (pageSize !== undefined) query.pageSize = parseInt(pageSize, 10)

    return c.json(await getCustomerListPaginated(query))
  }

  // Default: compact selector shape for POS dropdown consumers
  const result = await getCustomerList()
  return c.json(result as CustomerListResponse)
})

// ---------------------------------------------------------------------------
// GET /customers/:id — Get single customer detail
// ---------------------------------------------------------------------------

customersRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')
  const customer = await getCustomerById(id)

  if (!customer) {
    return c.json({ error: 'Customer not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json(customer)
})

// ---------------------------------------------------------------------------
// POST /customers — Create a new customer
// ---------------------------------------------------------------------------

customersRoutes.post('/', async (c) => {
  const input = await c.req.json()

  try {
    const validated = createCustomerSchema.parse(input)
    const customer = await createCustomer(validated)
    return c.json(customer, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      // Invalid JSON body
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }
    // Zod validation error
    return c.json({ error: 'Validation failed', code: 'VALIDATION_ERROR' }, 400)
  }
})

// ---------------------------------------------------------------------------
// PATCH /customers/:id — Update a customer (partial update allowed)
// ---------------------------------------------------------------------------

customersRoutes.patch('/:id', async (c) => {
  const id = c.req.param('id')

  try {
    const input = await c.req.json()
    const validated = updateCustomerSchema.parse(input)
    const customer = await updateCustomer(id, validated)
    return c.json(customer)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    if (err instanceof CustomerNotFoundError) {
      return c.json({ error: 'Customer not found', code: 'NOT_FOUND' }, 404)
    }

    // Zod validation error
    return c.json({ error: 'Validation failed', code: 'VALIDATION_ERROR' }, 400)
  }
})

// ---------------------------------------------------------------------------
// DELETE /customers/:id — Delete a customer (with blocking logic)
// ---------------------------------------------------------------------------

customersRoutes.delete('/:id', async (c) => {
  const id = c.req.param('id')

  try {
    await deleteCustomer(id)
    return c.json({ success: true })
  } catch (err) {
    if (err instanceof CustomerNotFoundError) {
      return c.json({ error: 'Customer not found', code: 'NOT_FOUND' }, 404)
    }

    if (err instanceof DeleteBlockedError) {
      return c.json({ error: err.message, code: 'CONFLICT' }, 409)
    }

    console.error('[DELETE /customers/:id] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

